  "La IA viene incluida con tu cuenta de Revela, sin claves: inicia sesión y listo.": "De AI zit in je Revela-account, zonder sleutels: log in en klaar.",
  "Revela usa OpenRouter, que da acceso a muchos modelos (Claude, GPT, Gemini, Llama…). Entras con tu cuenta de OpenRouter y pagas allí lo que uses.": "Revela gebruikt OpenRouter, dat toegang geeft tot veel modellen (Claude, GPT, Gemini, Llama…). Je logt in met je OpenRouter-account en betaalt daar wat je gebruikt.",
  "Opciones avanzadas": "Geavanceerde opties",
  "En lugar de la IA incluida, tu propia cuenta de OpenRouter:": "In plaats van de meegeleverde AI, je eigen OpenRouter-account:",
  "Descartar la actual": "Huidige verwerpen",
  "Colaborar en directo con el servidor de Revela: quien tenga un enlace verá los cambios al momento y, según el enlace, podrá comentar o editar. La presentación se guarda allí mientras dure la sesión (aunque cierres esta pestaña) y se borra al terminarla.": "Live samenwerken via de Revela-server: iedereen met een link ziet de wijzigingen meteen en kan, afhankelijk van de link, reageren of bewerken. De presentatie wordt daar bewaard zolang de sessie duurt (ook als je dit tabblad sluit) en daarna verwijderd.",
  "Empezar a colaborar": "Beginnen met samenwerken",
  "Opciones avanzadas (administradores)": "Geavanceerde opties (beheerders)",
  "ejemplo.com": "voorbeeld.nl",
  "Mi propio proyecto de Google Cloud (avanzado)": "Mijn eigen Google Cloud-project (geavanceerd)",
  "Avanzado: usar mi propio proyecto de Google Cloud (no hace falta para usar Drive)": "Geavanceerd: mijn eigen Google Cloud-project gebruiken (niet nodig voor Drive)",
  "No se puede conectar el móvil: comprueba la conexión a internet.": "De telefoon kan geen verbinding maken: controleer de internetverbinding.",
  "No se puede conectar: comprueba la conexión a internet del móvil y vuelve a intentarlo.": "Geen verbinding: controleer de internetverbinding van de telefoon en probeer het opnieuw.",
  "Al presentar aparece un QR: el público vota desde el móvil y los resultados se actualizan al instante. Los móviles se conectan directamente a este ordenador, sin servidor; funciona bien con decenas de personas.": "Tijdens het presenteren verschijnt een QR-code: het publiek stemt met de telefoon en de resultaten worden meteen bijgewerkt. De telefoons verbinden rechtstreeks met deze computer, zonder server; het werkt goed met tientallen mensen.",
  "GIF animado": "Geanimeerde GIF",
  "≈ {s} s de vídeo ({n} diapositivas); hacerlo tarda unos minutos.": "≈ {s} s video ({n} dia’s); het maken duurt een paar minuten.",
  "Vídeo descargado.": "Video gedownload.",
