  "Se abre una copia: para guardar los cambios, guárdala en Drive.": "Er wordt een kopie geopend: sla die op in Drive om je wijzigingen te bewaren.",
  "Nueva conversación: la IA olvida los mensajes anteriores (sigue viendo la presentación)": "Nieuw gesprek: de AI vergeet de eerdere berichten (ziet de presentatie nog wel)",
  "Recuerda {n} mensajes": "Onthoudt {n} berichten",
  "Para una pregunta nueva, «Nueva» la vacía: gasta menos.": "Voor een nieuwe vraag maakt «Nieuw» het leeg: dat kost minder.",
  "Hay cambios propuestos sin aplicar. ¿Empezar una conversación nueva y descartarlos?": "Er zijn voorgestelde wijzigingen die nog niet zijn toegepast. Een nieuw gesprek beginnen en ze verwerpen?",
  "Con disparador": "Met trigger",
  "(varios)": "(meerdere)",
  "Elige una animación para ver sus opciones. Ctrl o Mayús: varias a la vez.": "Kies een animatie om de opties te zien. Ctrl of Shift: meerdere tegelijk.",
  "Ampliar una zona de esta lupa": "Een deel van dit vergrootglas vergroten",
  "No se pudo guardar": "Opslaan mislukt",
  "Con «Solo las personas añadidas», el enlace solo lo abren las personas de arriba. Para que lo abra cualquiera, elige «Cualquiera con el enlace puede ver».": "Met «Alleen toegevoegde personen» kunnen alleen de personen hierboven de link openen. Kies «Iedereen met de link kan bekijken» zodat iedereen hem kan openen.",
  "Reconectando…": "Opnieuw verbinden…",
  "Se ha perdido la conexión. Pulsa «Conectar» para volver.": "De verbinding is verbroken. Tik op «Verbinden» om terug te gaan.",
  "Puedes cerrar esta ventana: el móvil sigue conectado mientras presentas.": "Je kunt dit venster sluiten: de telefoon blijft verbonden tijdens het presenteren.",
  "Apagar el mando": "Afstandsbediening uitzetten",
  "No se pudo conectar. Comprueba el código en el ordenador; si sigue sin ir, conecta el móvil a la misma wifi que el ordenador y vuelve a intentarlo.": "Verbinden mislukt. Controleer de code op de computer; lukt het nog steeds niet, verbind de telefoon dan met dezelfde wifi als de computer en probeer het opnieuw.",
  "Insertar en una web (iframe)": "Insluiten in een webpagina (iframe)",
  "Se ve como presentación, sin el editor, y siempre con los últimos cambios.": "Wordt getoond als presentatie, zonder de editor, en altijd met de laatste wijzigingen.",
  "Esta presentación no es pública. Quien la comparte debe elegir «Cualquiera con el enlace puede ver».": "Deze presentatie is niet openbaar. Wie hem deelt, moet «Iedereen met de link kan bekijken» kiezen.",
  "Para usarlo sin las barras del navegador: Compartir ▸ «Añadir a pantalla de inicio». Se abre como una app.": "Gebruik het zonder de balken van de browser: Deel ▸ «Zet op beginscherm». Het opent als een app.",
  "La presentación se ha movido en Drive a «{f}»: se sigue guardando ahí.": "De presentatie is in Drive verplaatst naar «{f}»: hij wordt daar verder opgeslagen.",
  "La presentación se ha movido a otra carpeta de Drive: se sigue guardando ahí.": "De presentatie is naar een andere Drive-map verplaatst: hij wordt daar verder opgeslagen.",
  "En Drive ahora se llama «{n}».": "In Drive heet hij nu «{n}».",
  "No encuentro «{n}» en Drive: se ha borrado o ya no tienes acceso. ¿La guardas de nuevo en Drive?": "Ik kan «{n}» niet vinden in Drive: verwijderd of je hebt geen toegang meer. Opnieuw in Drive opslaan?",
  "Patrocinado": "Gesponsord",
  "Con Transformar, su duración se cambia en Configuración de la presentación": "Met Transformeren stel je de duur in bij Presentatie-instellingen",
  "Esta diapositiva usa Transformar, pero este objeto entra con su animación: no se desliza desde la anterior. Quita su animación de entrada para que se deslice.": "Deze dia gebruikt Transformeren, maar dit object komt binnen met zijn animatie: het glijdt niet vanaf de vorige. Verwijder de ingangsanimatie zodat het glijdt.",
  "Este objeto sale con su animación en la diapositiva anterior: aquí aparece sin deslizarse.": "Dit object verdwijnt met zijn animatie op de vorige dia: hier verschijnt het zonder te glijden.",
  "Recuperar": "Herstellen",
  "«{n}» tenía cambios: se ha guardado una copia en este navegador (Archivo ▸ Versiones).": "«{n}» had wijzigingen: er is een kopie bewaard in deze browser (Bestand ▸ Versies).",
  "Antes de abrir otra presentación": "Voor het openen van een andere presentatie",
  "Se guardan en este navegador: automáticamente cada pocos minutos mientras editas, al abrir otra presentación (la que tenías, si había cambios) y cuando guardas una versión con nombre.": "Ze worden bewaard in deze browser: automatisch om de paar minuten tijdens het bewerken, bij het openen van een andere presentatie (de vorige, als die wijzigingen had) en wanneer je een versie met naam opslaat.",
