  "Cada clic de «siguiente» reproduce el tramo siguiente y se para al final. Si empieza solo, el primer tramo se reproduce al llegar. Sin tramos, un clic lo reproduce entero.": "Elke klik op «volgende» speelt het volgende fragment af en stopt aan het einde ervan. Als de video automatisch start, wordt het eerste fragment bij aankomst afgespeeld. Zonder fragmenten speelt één klik alles af.",
