  "Este navegador no tiene reconocimiento de voz: el entrenador funciona en Chrome, Edge y Safari.": "Deze browser heeft geen spraakherkenning: de coach werkt in Chrome, Edge en Safari.",
  "El entrenador escucha mientras ensayas para medir tu ritmo y tus muletillas. Usa el reconocimiento de voz del navegador: en Chrome y Edge el audio se envía a su servicio de voz. ¿Empezar?": "De coach luistert terwijl je repeteert om je tempo en stopwoorden te meten. Hij gebruikt de spraakherkenning van de browser: in Chrome en Edge wordt de audio naar hun spraakdienst gestuurd. Beginnen?",
