  "No se pudo leer tu Drive.": "Je Drive kon niet worden gelezen.",
  "Revela ya viene preparado para Google Drive. Solo si quieres usar tu propio proyecto de Google Cloud (permiso drive.file), escribe aquí su ID de cliente, su clave de API y su número de proyecto; se guardan solo en este navegador. Déjalo vacío para usar el de Revela.": "Revela is al klaar voor Google Drive. Alleen als je je eigen Google Cloud-project (machtiging drive.file) wilt gebruiken, vul je hier de client-ID, API-sleutel en het projectnummer in; ze worden alleen in deze browser opgeslagen. Laat leeg om dat van Revela te gebruiken.",
  "Número de proyecto": "Projectnummer",
  "Vuelve a iniciar sesión con Google.": "Log opnieuw in met Google.",
  "La presentación ha cambiado en Drive desde otro dispositivo. Elige qué versión quedarse en el aviso de arriba.": "De presentatie is in Drive gewijzigd op een ander apparaat. Kies in de melding hierboven welke versie je wilt houden.",
  "Firmas digitales": "Digitale handtekeningen",
  "Firmar": "Ondertekenen",
