  "Tu huella de firma:": "Je handtekeningvingerafdruk:",
  "La firma se hace con una clave que no sale de este navegador. Da tu huella a quien quiera comprobar que la firma es tuya. Al firmar, la presentación queda marcada como final.": "De handtekening wordt gemaakt met een sleutel die deze browser nooit verlaat. Geef je vingerafdruk aan wie wil controleren dat de handtekening van jou is. Bij ondertekenen wordt de presentatie als definitief gemarkeerd.",
  "Quitar las firmas": "Handtekeningen verwijderen",
  "Esta presentación no está firmada.": "Deze presentatie is niet ondertekend.",
  "Huella:": "Vingerafdruk:",
  "Escribe tu nombre para firmar.": "Vul je naam in om te ondertekenen.",
  "No se pudo firmar: ": "Ondertekenen mislukt: ",
  "¿Quitar todas las firmas?": "Alle handtekeningen verwijderen?",
  "Esta presentación está firmada. Si la cambias, las firmas dejarán de ser válidas. ¿Editarla de todos modos?": "Deze presentatie is ondertekend. Als je haar wijzigt, zijn de handtekeningen niet meer geldig. Toch bewerken?",
  "Firmada por": "Ondertekend door",
  "la presentación es de solo lectura.": "de presentatie is alleen-lezen.",
  "Tu nombre (lo verán los demás):": "Je naam (zichtbaar voor anderen):",
  "Colaborar en directo: quien tenga un enlace verá los cambios al momento y, según el enlace, podrá comentar o editar. Los datos van directamente entre los navegadores (cifrados); esta pestaña debe seguir abierta mientras dure la sesión. ¿Empezar?": "Live samenwerken: iedereen met een link ziet wijzigingen direct en kan, afhankelijk van de link, reageren of bewerken. De gegevens gaan rechtstreeks tussen de browsers (versleuteld); dit tabblad moet open blijven zolang de sessie duurt. Starten?",
  "No se pudo empezar la sesión: ": "Kan sessie niet starten: ",
  "Colaborar": "Samenwerken",
