  "Ese enlace ya no es válido.": "Die link is niet meer geldig.",
  "No se pudo conectar con la sesión: ¿sigue abierta en el navegador de quien la compartió?": "Kan geen verbinding maken met de sessie: is die nog open in de browser van degene die hem heeft gedeeld?",
  "La sesión de colaboración ha terminado. ¿Descargar una copia de la presentación? Después vuelves a la tuya.": "De samenwerkingssessie is beëindigd. Een kopie van de presentatie downloaden? Daarna ga je terug naar je eigen presentatie.",
  "No se pudo guardar la presentación actual en Drive. ¿Abrir la otra de todos modos? La actual se perderá.": "De huidige presentatie kon niet in Drive worden opgeslagen. Toch de andere openen? De huidige gaat verloren.",
