  "Inicia sesión con Google para ver tus presentaciones de Revela en Drive, abrirlas desde cualquier equipo y guardarlas solas mientras trabajas. Revela solo puede ver los archivos que crea o que abres con él.": "Log in met Google om je Revela-presentaties in Drive te zien, ze op elk apparaat te openen en ze automatisch op te slaan terwijl je werkt. Revela kan alleen de bestanden zien die het zelf maakt of die je ermee opent.",
