  "Editar a la vez con otras personas: enlaces para ver, comentar o editar, y chat": "Tegelijk met anderen bewerken: links om te bekijken, reageren of bewerken, en chat",
  "Presentar en una videollamada": "Presenteren in een videogesprek",
  "La presentación se abre en una ventana aparte. En la llamada, comparte esa ventana: así los demás ven solo las diapositivas y tú sigues teniendo Revela a mano.": "De presentatie opent in een apart venster. Deel dat venster in het gesprek: de anderen zien alleen de dia's en jij houdt Revela bij de hand.",
  "Presentar ahora ▸ Una ventana ▸ elige la de tu presentación.": "Nu presenteren ▸ Een venster ▸ kies dat van je presentatie.",
  "Compartir ▸ Ventana ▸ elige la de tu presentación.": "Delen ▸ Venster ▸ kies dat van je presentatie.",
  "Compartir pantalla ▸ elige la ventana de tu presentación.": "Scherm delen ▸ kies het venster van je presentatie.",
  "Pasa las diapositivas con las flechas en esa ventana. Pulsa S allí para abrir las notas del orador en otra ventana, que no compartes.": "Blader in dat venster met de pijltjestoetsen door de dia’s. Druk daar op S om de sprekersnotities te openen in een ander venster, dat je niet deelt.",
  "Abrir la ventana de presentación": "Presentatievenster openen",
  "El navegador ha bloqueado la ventana: permite las ventanas emergentes de este sitio y vuelve a intentarlo.": "De browser heeft het venster geblokkeerd: sta pop-ups toe voor deze site en probeer het opnieuw.",
  "En una<br>videollamada": "In een<br>videogesprek",
  "Para Google Meet, Microsoft Teams o Zoom: la presentación en una ventana que compartes": "Voor Google Meet, Microsoft Teams of Zoom: de presentatie in een venster dat je deelt",
  "Privacidad": "Privacy",
  "Condiciones": "Voorwaarden",
  "Colaborar en directo con tu servidor: quien tenga un enlace verá los cambios al momento y, según el enlace, podrá comentar o editar. La presentación se guarda en tu servidor mientras dure la sesión (aunque cierres esta pestaña) y se borra al terminarla. ¿Empezar?": "Live samenwerken met je server: wie een link heeft, ziet wijzigingen meteen en kan, afhankelijk van de link, opmerkingen plaatsen of bewerken. De presentatie blijft tijdens de sessie op je server (ook als je dit tabblad sluit) en wordt aan het einde verwijderd. Beginnen?",
  "El servidor no tiene activada la colaboración (falta el Durable Object ROOMS).": "Op de server is samenwerken niet ingeschakeld (het Durable Object ROOMS ontbreekt).",
  "No se pudo conectar con el servidor.": "Kan geen verbinding maken met de server.",
  "La clave de subida no es correcta.": "De uploadsleutel is niet juist.",
  "La presentación es demasiado grande para el servidor.": "De presentatie is te groot voor de server.",
  "El servidor respondió ": "De server antwoordde ",
