  "GIF animados con licencias libres (Wikimedia y otros). Se añade la atribución como pie: mantenla si la licencia lo pide.": "Geanimeerde GIF's met vrije licenties (Wikimedia en andere). De naamsvermelding wordt als bijschrift toegevoegd: laat die staan als de licentie dat vereist.",
  "Emojis animados de Google (Noto, CC BY 4.0). Se pueden animar por tramos y quitar el fondo como cualquier GIF.": "Geanimeerde emoji van Google (Noto, CC BY 4.0). Je kunt ze in delen animeren en de achtergrond verwijderen zoals bij elke GIF.",
  "Modelos 3D con licencia libre, varios con animaciones propias (andar, bailar…). Se guardan dentro de la presentación. Muévelos con clic derecho ▸ Movimiento 3D.": "3D-modellen met vrije licentie, sommige met eigen animaties (lopen, dansen…). Ze worden in de presentatie opgeslagen. Beweeg ze met rechtsklik ▸ 3D-beweging.",
  "Más de 500 modelos 3D de Poly Haven, de dominio público (CC0). Se guardan dentro de la presentación.": "Meer dan 500 3D-modellen van Poly Haven, uit het publieke domein (CC0). Ze worden in de presentatie opgeslagen.",
  "Millones de modelos 3D de Sketchfab, muchos animados. Se muestran con el visor de Sketchfab (necesita internet al presentar).": "Miljoenen 3D-modellen van Sketchfab, veel geanimeerd. Ze worden getoond met de Sketchfab-viewer (internet nodig tijdens het presenteren).",
