  "Más de 250 modelos de la NASA: naves, satélites, cohetes, róveres, asteroides… Libres y sin copyright (sin usar sus logotipos como aval). Se guardan dentro de la presentación.": "Meer dan 250 NASA-modellen: ruimtevaartuigen, satellieten, raketten, rovers, asteroïden… Vrij en zonder auteursrecht (gebruik hun logo's niet als aanbeveling). Worden in de presentatie opgeslagen.",
  "Miles de modelos 3D de Wikimedia Commons (fósiles, piezas de museo, anatomía, edificios…) con licencias libres; se añade la atribución como pie. Busca en inglés para más resultados.": "Duizenden 3D-modellen van Wikimedia Commons (fossielen, museumstukken, anatomie, gebouwen…) met vrije licenties; de naamsvermelding wordt als bijschrift toegevoegd. Zoek in het Engels voor meer resultaten.",
