  "¿Conectar la aplicación de escritorio de Revela a tu cuenta ({email})? Hazlo solo si acabas de pedirlo tú y la aplicación muestra este código: {code}": "De Revela-desktopapp aan je account ({email}) koppelen? Doe het alleen als je het net zelf hebt gevraagd en de app deze code toont: {code}",
