  "¿Eliminar esta presentación de la nube? Quien la tenga compartida dejará de verla. No se puede deshacer.": "Deze presentatie uit de cloud verwijderen? Wie ermee gedeeld is, ziet hem niet meer. Dit kan niet ongedaan worden.",
  "Para compartirla con personas concretas o por enlace, guárdala en tu nube de Revela. Los cambios se guardan solos y quien tenga permiso los ve.": "Om hem met bepaalde mensen of via een link te delen, sla je hem op in je Revela-cloud. Wijzigingen worden automatisch opgeslagen en iedereen met toegang ziet ze.",
