  "¿Restaurar esta versión? Se aplicará para todos; la actual queda como versión.": "Deze versie terugzetten? Het geldt voor iedereen; de huidige blijft bewaard als versie.",
  "Esta presentación está compartida con personas concretas. Inicia sesión con tu cuenta de Google para abrirla.": "Deze presentatie is gedeeld met bepaalde mensen. Meld je aan met je Google-account om hem te openen.",
  "Tu cuenta ({email}) no tiene acceso a esta presentación. Pide a quien te la envió que te añada.": "Je account ({email}) heeft geen toegang tot deze presentatie. Vraag degene die hem stuurde om je toe te voegen.",
