  "Colocar:": "Plaatsen:",
  "Escribe los elementos en el orden correcto, uno por línea: en los móviles salen desordenados.": "Schrijf de items in de juiste volgorde, één per regel: op de telefoons staan ze door elkaar.",
  "Una pareja por línea: «izquierda = derecha». En los móviles, la columna derecha sale desordenada.": "Eén paar per regel: \"links = rechts\". Op de telefoons staat de rechterkolom door elkaar.",
  "Escribe el texto y pon cada respuesta entre corchetes. Da igual mayúsculas y tildes.": "Schrijf de tekst en zet elk antwoord tussen vierkante haken. Hoofdletters en accenten tellen niet.",
  "Escribe las etiquetas (una por línea), elige una imagen y haz clic en ella para colocar cada etiqueta.": "Schrijf de labels (één per regel), kies een afbeelding en klik erop om elk label te plaatsen.",
  "La capital de Francia es [París]. Varias respuestas válidas: [coche|automóvil].": "De hoofdstad van Frankrijk is [Parijs]. Meerdere goede antwoorden: [auto|wagen].",
  "En sus<br>dispositivos": "Op hun<br>apparaten",
