  "Al presentar, el público sigue las diapositivas en su móvil o portátil (con un código y un QR en la esquina) y responde desde ahí las actividades": "Tijdens het presenteren volgt het publiek de dia's op hun telefoon of laptop (met een code en QR-code in de hoek) en beantwoordt daar de activiteiten",
  "Puntos de cada participante en cada cuestionario y actividad, y descarga en CSV": "Punten van elke deelnemer bij elke quiz en activiteit, en download als CSV",
