  "Ordena los ejemplos para ti. Puedes cambiarlo en la configuración de la presentación.": "De voorbeelden worden voor je gesorteerd. Je kunt dit wijzigen in de instellingen van de presentatie.",
  "Uso principal": "Hoofdgebruik",
  "Uso de Revela (en este navegador)": "Gebruik van Revela (in deze browser)",
  "Qué ejemplos ves primero y, para empresa, sin los botones solo para docentes (siguen en la búsqueda de comandos).": "Welke voorbeelden je eerst ziet en, voor bedrijven, zonder de knoppen die alleen voor docenten zijn (ze staan nog in de opdrachtenzoeker).",
  "Marca de agua": "Watermerk",
  "Marca de agua «Confidencial» al presentar, compartir y exportar": "Watermerk „Vertrouwelijk” bij presenteren, delen en exporteren",
  "CONFIDENCIAL": "VERTROUWELIJK",
  "Con el correo de quien la abre (enlaces con seguimiento que piden el correo)": "Met het e-mailadres van wie hem opent (gevolgde links die om het e-mailadres vragen)",
  "En diagonal y discreta sobre cada diapositiva: en el visor, al presentar, en la página web y en el PDF. Quien la ve no puede quitarla, pero es un aviso que disuade, no una protección: una copia se puede manipular y una pantalla siempre se puede fotografiar.": "Diagonaal en subtiel over elke dia: in de viewer, tijdens het presenteren, op de webpagina en in de pdf. Kijkers kunnen het niet weghalen, maar het schrikt alleen af en beschermt niet: een kopie kan worden aangepast en een scherm kan altijd worden gefotografeerd.",
  "¿Una marca de agua «Confidencial» con su correo? Transiciones ▸ Configuración ▸ Marca de agua.": "Een watermerk „Vertrouwelijk” met hun e-mailadres? Overgangen ▸ Instellingen ▸ Watermerk.",
  "Participante": "Deelnemer",
  "p. ej.: Resultados del trimestre para el comité de dirección": "bijv.: Kwartaalresultaten voor het directieteam",
  "Reunión general (all-hands)": "Algemene bijeenkomst (all-hands)",
  "Para toda la empresa: cifras una a una, hitos en cronología, objetivos en barras, bienvenidas, nube de palabras y preguntas anónimas desde el móvil": "Voor het hele bedrijf: cijfers één voor één, mijlpalen op een tijdlijn, doelen als balken, welkomstwoorden, een woordwolk en anonieme vragen via de telefoon",
  "Revisión trimestral con un cliente (QBR)": "Kwartaalreview met een klant (QBR)",
  "Objetivos acordados frente a resultados, gráficos de líneas y barras, ahorro en cascada con Transformar, plan del trimestre y próximos pasos con responsables": "Afgesproken doelen tegenover resultaten, lijn- en staafdiagrammen, besparingen als watervaldiagram met Transformeren, het kwartaalplan en volgende stappen met verantwoordelijken",
  "Caso de éxito": "Klantsucces",
  "Historia de un cliente: el reto en tarjetas, la solución paso a paso, el resultado con Transformar y un gráfico antes y después, testimonio y llamada a la acción": "Het verhaal van een klant: de uitdaging op kaarten, de oplossing stap voor stap, het resultaat met Transformeren en een voor-en-na-grafiek, een getuigenis en een oproep tot actie",
  "Webinar": "Webinar",
  "Seminario web: normas para asistentes, votación inicial, demo en tres pasos con Transformar, preguntas del público desde el móvil y llamada a la acción con enlaces": "Online seminar: afspraken voor deelnemers, een openingspeiling, een demo in drie stappen met Transformeren, vragen van het publiek via de telefoon en een oproep tot actie met links",
  "Kickoff de ventas": "Sales kick-off",
  "Inicio del año comercial: Transformar en la portada, ventas frente al objetivo, rectángulos por sector, embudo, objetivo por región, palancas, plan de comisiones, premios y cuenta atrás para el café": "Start van het verkoopjaar: Transformeren op de titeldia, verkoop tegenover doel, een treemap per sector, de trechter, het doel per regio, hefbomen, het commissieplan, prijzen en een aftelling naar de koffiepauze",
  "Los puntos de cada cuestionario y actividad, guardados en este navegador la última vez que se presentó. Activa Ver ▸ Público ▸ En sus dispositivos para que cada participante siga las diapositivas en el suyo.": "De punten van elke quiz en activiteit, in deze browser bewaard sinds de laatste presentatie. Zet Beeld ▸ Publiek ▸ Op hun apparaten aan zodat elke deelnemer de dia's op zijn eigen apparaat volgt.",
  "Esta presentación no tiene cuestionarios ni actividades con nota.": "Deze presentatie heeft geen quizzen of beoordeelde activiteiten.",
  "Aún no hay respuestas: presenta y deja que el público responda.": "Nog geen antwoorden: presenteer en laat het publiek antwoorden.",
