  "Los colores y fuentes del tema son la base; los estilos de texto deciden qué usa cada nivel (título, subtítulo y 5 niveles de texto) en el patrón y todos sus diseños": "De themakleuren en -lettertypen zijn de basis; de tekststijlen bepalen wat elk niveau gebruikt (titel, ondertitel en 5 tekstniveaus) in het model en al zijn indelingen",
