  "Los colores y fuentes del tema son la base; los estilos de texto deciden qué usa cada nivel. Un color o una fuente «del tema» cambia con Diseño ▸ Colores y Fuentes; uno propio, no.": "De themakleuren en -lettertypen zijn de basis; de tekststijlen bepalen wat elk niveau gebruikt. Een kleur of lettertype \"van het thema\" verandert mee met Ontwerp ▸ Kleuren en Lettertypen; een eigen niet.",
  "Quitar formato propio": "Eigen opmaak wissen",
  "Marcadores de diseños y diapositivas con formato propio (tamaño, color, fuente…): no cambian con el estilo. Quítalo para que lo sigan.": "Tijdelijke aanduidingen in indelingen en dia's met eigen opmaak (grootte, kleur, lettertype…): ze veranderen niet mee met de stijl. Wis die zodat ze hem volgen.",
  "Lupa": "Vergrootglas",
  "Lupa: ampliar una zona. Dibuja un rectángulo sobre lo que quieres ampliar; el recuadro ampliado se coloca solo, con líneas que muestran de dónde sale": "Vergrootglas: een gebied vergroten. Teken een rechthoek over wat je wilt vergroten; het vergrote kader plaatst zichzelf, met lijnen die tonen waar het vandaan komt",
