  "¿Eliminar la carpeta vacía «{name}»?": "De lege map ‘{name}’ verwijderen?",
  "¿Eliminar la carpeta «{name}»? Lo que contiene pasará a «{up}»; no se borra ninguna presentación.": "De map ‘{name}’ verwijderen? De inhoud gaat naar ‘{up}’; er wordt geen presentatie verwijderd.",
  "¿Eliminar «{name}» para siempre? No se puede deshacer.": "‘{name}’ definitief verwijderen? Dit kan niet ongedaan worden gemaakt.",
  "¿Mover «{name}» a la papelera? Podrás restaurarla durante {n} días; después se borrará para siempre. Mientras tanto, quien la tenga compartida no podrá abrirla.": "‘{name}’ naar de prullenbak verplaatsen? Je kunt hem {n} dagen herstellen; daarna wordt hij definitief verwijderd. Intussen kunnen mensen met wie hij gedeeld is hem niet openen.",
  "¿Vaciar la papelera? Lo que hay en ella se borrará para siempre.": "Prullenbak legen? Alles erin wordt definitief verwijderd.",
  "Última modificación": "Laatst gewijzigd",
  "Abrir el mando": "Afstandsbediening openen",
  "Amplía ×2 la zona bajo el dedo. Pellizca para cambiar el tamaño de la lupa.": "Vergroot het gebied onder je vinger ×2. Knijp om de grootte van het vergrootglas te wijzigen.",
  "Cargando conexión…": "Verbinding laden…",
  "Conecta con la presentación": "Verbind met de presentatie",
  "Conectando…": "Verbinden…",
  "Desconectado": "Verbinding verbroken",
  "Desconectar el móvil": "Telefoon loskoppelen",
  "Empieza a presentar en el ordenador para usar el panel.": "Start de presentatie op de computer om het touchpad te gebruiken.",
  "En el móvil, escanea el QR (o abre esta dirección e introduce el código). Podrás ver las notas, pasar diapositivas y usar el panel táctil: puntero, foco, lupa y tocar la diapositiva.": "Scan op je telefoon de QR-code (of open dit adres en voer de code in). Je ziet de notities, wisselt van dia en gebruikt het touchpad: aanwijzer, spotlight, vergrootglas en tikken op de dia.",
  "En el ordenador: Ver ▸ Conectar móvil. Escribe aquí el código:": "Op de computer: Beeld ▸ Telefoon koppelen. Typ hier de code:",
  "Error de conexión: ": "Verbindingsfout: ",
  "Error: ": "Fout: ",
  "Esa web es de otro sitio: el navegador no deja que el mando la toque ni la desplace.": "Die webpagina komt van een andere site: de browser laat de afstandsbediening er niet op tikken of in scrollen.",
  "Escribe el código completo.": "Typ de volledige code.",
  "Esperando a que quien presenta lo permita…": "Wachten tot de presentator toestemming geeft…",
  "Esperando al móvil…": "Wachten op de telefoon…",
  "Esperando…": "Wachten…",
  "Foco": "Spotlight",
  "Ilumina una zona y oscurece el resto. Cuanto más aprietes o más tiempo mantengas el dedo, mayor es el foco; pellizca para cambiar su tamaño.": "Licht één gebied op en dimt de rest. Hoe harder of langer je drukt, hoe groter de spotlight; knijp om de grootte te wijzigen.",
  "Iniciando…": "Starten…",
