  "Mando conectado": "Afstandsbediening verbonden",
  "Mueve el dedo: el público ve un punto rojo con estela. Pellizca con dos dedos para ampliar la diapositiva.": "Beweeg je vinger: het publiek ziet een rode stip met een spoor. Knijp met twee vingers om in te zoomen op de dia.",
  "Móvil conectado": "Telefoon verbonden",
  "No hay ninguna presentación con ese código.": "Er is geen presentatie met die code.",
  "No se pudo cargar la librería de conexión.": "De verbindingsbibliotheek kon niet worden geladen.",
  "Notas de esta diapositiva": "Notities bij deze dia",
  "Panel táctil": "Touchpad",
  "Pantalla negra": "Zwart scherm",
  "Permitir": "Toestaan",
  "Puntero": "Aanwijzer",
  "Quien presenta ha desconectado este mando.": "De presentator heeft deze afstandsbediening losgekoppeld.",
  "Quien presenta no ha permitido la conexión.": "De presentator heeft de verbinding niet toegestaan.",
  "Quitar pantalla negra": "Zwart scherm opheffen",
  "Reiniciar el cronómetro": "Timer opnieuw starten",
  "Sin conectar": "Niet verbonden",
  "Solo un móvil a la vez puede controlar la presentación. El enlace del QR lleva una clave; quien escriba solo el código necesita tu permiso. Al desconectarlo, el enlace anterior deja de valer.": "Slechts één telefoon tegelijk kan de presentatie bedienen. De QR-link bevat een sleutel; wie alleen de code typt, heeft je toestemming nodig. Na het loskoppelen werkt de oude link niet meer.",
  "Toca para pulsar; arrastra para mover; desliza con dos dedos para desplazar; pellizca para ampliar y toca dos veces para volver. Las webs de otros sitios no se pueden tocar desde aquí.": "Tik om te drukken; sleep om te verplaatsen; veeg met twee vingers om te scrollen; knijp om te zoomen en tik twee keer om terug te gaan. Webpagina’s van andere sites kun je hiervandaan niet aanraken.",
  "Un móvil ha escrito el código y pide controlar la presentación.": "Een telefoon heeft de code ingevoerd en vraagt de presentatie te bedienen.",
  "Un móvil pide el control": "Een telefoon vraagt de bediening",
