  "Para la primera serie. Si cambias las filas de datos, aplica primero y vuelve a abrir para elegir los colores.": "Voor de eerste reeks. Als je de gegevensrijen wijzigt, pas ze eerst toe en open opnieuw om de kleuren te kiezen.",
  "El de la paleta": "Die van het palet",
  "Tres cuartos (al otro lado)": "Driekwart (andere kant)",
