  "Las palabras del público aparecerán aquí": "De woorden van het publiek verschijnen hier",
  "Agrandar 130 % y después Encoger 77 % lo deja como estaba": "Vergroten 130 % en daarna Verkleinen 77 % laat het zoals het was",
  "Qué diapositivas ve": "Welke dia's te zien zijn",
  "{n} de {m} diapositivas": "{n} van {m} dia's",
  "Todas las diapositivas": "Alle dia's",
  "El enlace": "De link",
  "(sin título)": "(zonder titel)",
  "oculta": "verborgen",
  "Las demás no le llegan: ni su contenido ni su título. Puedes ampliar o reducir la elección cuando quieras; las diapositivas nuevas no se añaden solas.": "De andere bereiken die persoon niet: inhoud noch titel. Je kunt de keuze altijd uitbreiden of verkleinen; nieuwe dia's worden niet vanzelf toegevoegd.",
  "Te ha compartido solo algunas diapositivas: puede añadir más cuando quiera.": "Er zijn maar enkele dia's met je gedeeld: er kunnen er later meer bij komen.",
  "Cada tramo puede ir a su velocidad: pasa deprisa (2×, 4×…) por lo que hay entre las partes que interesan y vuelve a la normal en ellas. «Igual» usa la velocidad de arriba.": "Elk fragment kan zijn eigen snelheid hebben: snel (2×, 4×…) door wat tussen de belangrijke delen zit en daarin weer normaal. „Hetzelfde” gebruikt de snelheid hierboven.",
  "Esquema": "Overzicht",
  "Revísalo antes de crear: cambia los títulos y los puntos, quita o añade diapositivas y ordénalas. Las diapositivas seguirán este esquema.": "Bekijk het voordat je maakt: wijzig titels en punten, verwijder of voeg dia's toe en zet ze in volgorde. De dia's volgen dit overzicht.",
  "Añadir diapositiva": "Dia toevoegen",
  "Crear sin esquema": "Maken zonder overzicht",
  "Ver el esquema": "Overzicht bekijken",
  "Puntos (uno por línea)": "Punten (één per regel)",
  "Crear {n} diapositivas": "{n} dia's maken",
  "Cuestionario en directo": "Live quiz",
  "Cuestionario<br>en directo": "Live<br>quiz",
  "Revisar<br>presentación": "Presentatie<br>nakijken",
  "Revisar presentación": "Presentatie nakijken",
  "La IA lee toda la presentación y te dice qué cambiar, diapositiva a diapositiva": "De AI leest de hele presentatie en vertelt je wat je moet veranderen, dia voor dia",
  "Preguntas y actividades sobre la presentación que el público responde desde el móvil": "Vragen en activiteiten over de presentatie die het publiek op de telefoon beantwoordt",
  "La IA lee la presentación y prepara preguntas y actividades que el público responde desde el móvil, con puntos y clasificación. Puedes editarlas después como cualquier votación.": "De AI leest de presentatie en maakt vragen en activiteiten die het publiek op de telefoon beantwoordt, met punten en een ranglijst. Je kunt ze daarna bewerken zoals elke peiling.",
  "Cuántas": "Hoeveel",
