  "Pausar": "Pauzeren",
  "Recortar a una proporción…": "Bijsnijden tot verhouding…",
  "Quitar el recorte": "Bijsnijden ongedaan maken",
  "Recortar sobre la imagen": "Bijsnijden op de afbeelding",
  "Arrastra los bordes para recortar; Intro para terminar, Esc para dejarlo como estaba": "Sleep de randen om bij te snijden; Enter om te voltooien, Esc om het te laten zoals het was",
  "Diseñar con IA": "Ontwerpen met AI",
  "Diseñar plantilla con IA": "Sjabloon ontwerpen met AI",
  "Diseñar plantilla": "Sjabloon ontwerpen",
  "Diseñar la plantilla con IA": "Het sjabloon ontwerpen met AI",
  "La IA te propone tres diseños de la plantilla (colores, fuentes, fondo y adornos) a partir de lo que describas o de tu logo": "De AI stelt drie sjabloonontwerpen voor (kleuren, lettertypen, achtergrond en versieringen) op basis van je beschrijving of je logo",
  "Describe cómo la quieres (o adjunta tu logo) y la IA te propone tres diseños: colores, fuentes, fondo y adornos del patrón. Elige uno; se deshace con Ctrl+Z.": "Beschrijf hoe je het wilt (of voeg je logo toe) en de AI stelt drie ontwerpen voor: kleuren, lettertypen, achtergrond en versieringen van het model. Kies er een; Ctrl+Z maakt het ongedaan.",
  "«Congreso médico, sobrio, azul marino»; «para niños de primaria, alegre»…": "„Medisch congres, sober, marineblauw”; „voor basisschoolkinderen, vrolijk”…",
  "Describe la plantilla": "Beschrijf het sjabloon",
  "Diseñando…": "Ontwerpen…",
  "Diseño aplicado a toda la presentación.": "Ontwerp toegepast op de hele presentatie.",
  "La IA no devolvió diseños válidos. Prueba a describirlo de otra forma.": "De AI gaf geen geldige ontwerpen. Probeer het anders te beschrijven.",
  "Título de la presentación": "Titel van de presentatie",
  "Una idea clara en cada punto": "Eén duidelijk idee per punt",
  "El texto se lee así, sobre su fondo": "Zo leest de tekst op zijn achtergrond",
  "Y los colores del tema": "En de kleuren van het thema",
  "Diseñar plantilla<br>con IA": "Sjabloon<br>met AI",
  "Diseñar<br>plantilla": "Sjabloon<br>ontwerpen",
  "Partir de una plantilla (.pptx, .potx, .odp)…": "Uitgaan van een sjabloon (.pptx, .potx, .odp)…",
  "No se pudo leer la plantilla:": "Kan het sjabloon niet lezen:",
  "Pide los cambios que quieras sobre ella, o aplícala tal cual.": "Vraag de wijzigingen die je wilt, of pas het toe zoals het is.",
  "«Más moderna», «con mis colores», «el título centrado»…": "„Moderner”, „met mijn kleuren”, „de titel gecentreerd”…",
  "La plantilla tal cual.": "Het sjabloon zoals het is.",
  "Abriendo «{n}»…": "„{n}” wordt geopend…",
