  "Tipo de diapositiva": "Diatype",
  "Para hacerla a tu medida": "Om hem op maat te maken",
  "Responde lo que quieras (o sáltalo): cuanto más sepa de tu caso, más tuya será la presentación.": "Beantwoord wat je wilt (of sla het over): hoe meer het van je situatie weet, hoe meer de presentatie van jou wordt.",
  "¿Algo más que deba saber?": "Nog iets dat het moet weten?",
  "Para qué es, cuánto dura, tus datos, lo que no puede faltar…": "Waarvoor het is, hoe lang het duurt, je gegevens, wat er niet mag ontbreken…",
  "Saltar las preguntas": "Vragen overslaan",
  "Otra respuesta, o más detalle…": "Een ander antwoord, of meer detail…",
  "Segundo eje a la derecha": "Secundaire as rechts",
  "Las líneas del combinado (o las series después de la primera) con su propia escala: para dos magnitudes distintas, como la lluvia y la temperatura de un climograma": "De lijnen van de combinatiegrafiek (of de reeksen na de eerste) met een eigen schaal: voor twee verschillende grootheden, zoals de neerslag en de temperatuur van een klimaatgrafiek",
  "Título del segundo eje": "Titel van de secundaire as",
  "Este modelo lleva el logotipo de {marca}, que es una marca: puedes enseñarlo tal cual, pero no como si fuera tu marca ni para dar a entender que te respaldan.": "Dit model draagt het logo van {marca}, een merk: je mag het tonen zoals het is, maar niet alsof het jouw merk is of om te suggereren dat zij je steunen.",
  "Alguno de esos logotipos tiene además derechos de autor: para un uso comercial, pide permiso o elige otro modelo.": "Een van die logo’s valt bovendien onder het auteursrecht: vraag voor commercieel gebruik toestemming of kies een ander model.",
  "esperando aprobación": "wachten op goedkeuring",
  "Aprobar": "Goedkeuren",
  "Aún no hay preguntas.": "Nog geen vragen.",
  "Moderar las preguntas": "Vragen modereren",
  "Las nuevas esperan aquí a que las apruebes; en la pantalla solo se ve cuántas esperan.": "Nieuwe vragen wachten hier op je goedkeuring; op het scherm zie je alleen hoeveel er wachten.",
  "Aprobar cada pregunta antes de que salga en pantalla": "Elke vraag goedkeuren voordat ze op het scherm verschijnt",
  "Al presentar, la tecla M (o clic derecho ▸ «Moderar las preguntas») abre una ventana para aprobarlas, ocultarlas o descartarlas: llévala a tu pantalla. Las preguntas no llevan el nombre de quien pregunta.": "Tijdens het presenteren opent de toets M (of rechtsklik ▸ ‘Vragen modereren’) een venster om ze goed te keuren, te verbergen of te verwijderen: zet het op je eigen scherm. Vragen tonen de naam van de vraagsteller niet.",
  "Tapar las palabrotas": "Scheldwoorden afschermen",
  "Apuntador": "Autocue",
  "Las notas de cada diapositiva, grandes y desplazándose solas, en una ventana aparte: ponla junto a la cámara al grabar o en una videollamada": "De notities van elke dia, groot en vanzelf scrollend, in een apart venster: zet het naast de camera bij het opnemen of in een videogesprek",
  "Volver al principio": "Terug naar het begin",
  "Esta diapositiva no tiene notas: escríbelas debajo de la diapositiva y aparecerán aquí.": "Deze dia heeft geen notities: schrijf ze onder de dia en ze verschijnen hier.",
  "Quieto": "Stil",
  "Seguir": "Verder",
  "Pausa": "Pauze",
  "Dirección de la web de tu marca (p. ej. tuempresa.com)": "Website van je merk (bijv. jouwbedrijf.nl)",
  "Sacar la marca de la web": "Merk van de website halen",
  "Leyendo la web…": "Website lezen…",
  "Revisa lo que ha salido y guárdalo.": "Controleer het resultaat en sla het op.",
  "La web usa {f}, que no está en el catálogo: elige la más parecida.": "De website gebruikt {f}, dat niet in de catalogus staat: kies het meest gelijkende.",
  "Esa dirección no es válida.": "Dat adres is niet geldig.",
  "Demasiadas seguidas: espera un minuto.": "Te veel achter elkaar: wacht een minuut.",
  "Entra en tu cuenta para usarlo.": "Log in om het te gebruiken.",
  "No se pudo leer esa web (algunas no dejan que otros programas las lean).": "Kon die website niet lezen (sommige laten zich niet door andere programma's lezen).",
  "Actividad: clasificar en grupos": "Activiteit: in groepen sorteren",
  "Un grupo por línea: «Grupo: elemento, elemento, elemento». En los móviles salen todos los elementos desordenados y cada persona elige el grupo de cada uno.": "Eén groep per regel: ‘Groep: item, item, item’. Op de telefoons verschijnen alle items door elkaar en kiest iedereen bij elk item de groep.",
  "Lo que más le cuesta al grupo": "Wat de groep het moeilijkst vindt",
