  "Adaptar al nivel de lectura": "Aanpassen aan leesniveau",
  "La IA reescribe los textos para ese público, en su mismo idioma y sin cambiar los datos. Las notas no se tocan. Puedes deshacerlo con Ctrl+Z.": "De AI herschrijft de teksten voor dat publiek, in dezelfde taal en zonder de feiten te veranderen. De notities blijven ongewijzigd. Je kunt het ongedaan maken met Ctrl+Z.",
  "Para": "Voor",
