  "Revisa que quepan en su caja.": "Controleer of ze in hun vak passen.",
  "Reescribe los textos para otra edad o para lectura fácil, sin cambiar los datos": "Herschrijft de teksten voor een andere leeftijd of als makkelijk lezen, zonder de feiten te veranderen",
