  "Ensayar las preguntas del público": "Vragen van het publiek oefenen",
  "La IA prevé lo que te pueden preguntar al acabar, también lo difícil. Elige una, respóndela en voz alta o por escrito y te dice cómo ha ido.": "De AI voorspelt wat je aan het eind gevraagd kunt worden, ook de moeilijke vragen. Kies er een, beantwoord hem hardop of schriftelijk en je hoort hoe het ging.",
  "Prever las preguntas": "Vragen voorspellen",
