  "Importar preguntas": "Vragen importeren",
  "Cada pregunta, en una diapositiva nueva con su votación (cuestionario, unir parejas, completar huecos o número), detrás de la diapositiva actual.": "Elke vraag op een nieuwe dia met zijn peiling (quiz, paren verbinden, gaten invullen of getal), na de huidige dia.",
  "opción múltiple, verdadero/falso, emparejamiento, respuesta corta, numérica y huecos (cloze) de respuesta corta.": "meerkeuze, waar/onwaar, koppelen, kort antwoord, numeriek en cloze met korte antwoorden.",
  "el formato de texto de Moodle: =correcta ~incorrecta, {T}/{F}, parejas con ->, respuesta corta y numérica con #.": "het tekstformaat van Moodle: =juist ~fout, {T}/{F}, paren met ->, kort antwoord en numeriek met #.",
  "su plantilla de hoja de cálculo (pregunta, respuestas 1 a 4, tiempo y respuestas correctas).": "het spreadsheetsjabloon (vraag, antwoorden 1 tot 4, tijdslimiet en juiste antwoorden).",
  "una pregunta por fila: pregunta, respuesta correcta, incorrecta 1, incorrecta 2, incorrecta 3. Separado por comas o punto y coma; la primera fila puede ser de títulos. Solo con la correcta, es de respuesta corta (varias válidas separadas por |).": "één vraag per rij: vraag, juist antwoord, fout 1, fout 2, fout 3. Gescheiden door komma's of puntkomma's; de eerste rij mag kopjes bevatten. Met alleen het juiste is het een kort antwoord (meerdere geldige gescheiden door |).",
  "{n} preguntas para importar": "{n} vragen om te importeren",
