  "Insertar {n} diapositivas": "{n} dia's invoegen",
  "No se pudo leer ese archivo de preguntas.": "Dat vragenbestand kon niet worden gelezen.",
  "{n} preguntas insertadas, cada una en su diapositiva.": "{n} vragen ingevoegd, elk op een eigen dia.",
  "Exportar preguntas": "Vragen exporteren",
  "Los cuestionarios y actividades de la presentación ({n}), para un banco de preguntas de Moodle, Kahoot u otra herramienta.": "De quizzen en activiteiten van de presentatie ({n}), voor een vragenbank in Moodle, Kahoot of een ander hulpmiddel.",
  "{n} preguntas en este formato.": "{n} vragen in dit formaat.",
  "Preguntas exportadas: {n}.": "Geëxporteerde vragen: {n}.",
  "Una página web para estudiar por tu cuenta, también sin internet y en el móvil: fichas para darles la vuelta (recuerda cuáles sabes) y práctica de los cuestionarios y actividades, con la respuesta al momento y la nota al final.": "Een webpagina om zelfstandig te studeren, ook offline en op een telefoon: flitskaarten om om te draaien (onthoudt welke je kent) en oefenen met de quizzen en activiteiten, met meteen het antwoord en aan het eind de score.",
  "Practicar las preguntas": "De vragen oefenen",
  "Una ficha más por diapositiva: su título delante y su texto detrás": "Eén kaart extra per dia: de titel voorop en de tekst achterop",
  "{c} fichas y {p} preguntas para practicar.": "{c} flitskaarten en {p} vragen om te oefenen.",
  "Añade cuestionarios o actividades (Insertar ▸ Votación en directo) o marca las diapositivas.": "Voeg quizzen of activiteiten toe (Invoegen ▸ Livepeiling) of vink de dia's aan.",
  "Página de estudio descargada: se abre con cualquier navegador, también sin conexión.": "Studiepagina gedownload: hij opent in elke browser, ook offline.",
  "Cuestionario": "Quiz",
