  "Los cuestionarios y actividades como banco de preguntas: Moodle XML, GIFT, Kahoot (Excel) o CSV": "De quizzen en activiteiten als vragenbank: Moodle XML, GIFT, Kahoot (Excel) of CSV",
  "Una página para estudiar por tu cuenta: fichas que se dan la vuelta y práctica de los cuestionarios, también sin internet": "Een pagina om zelfstandig te studeren: flitskaarten om om te draaien en oefenen met de quizzen, ook offline",
  "Candado": "Slot",
  "Al presentar, un clic en el candado pide el código. Para escape rooms y retos: el código correcto lo abre.": "Tijdens het presenteren vraagt een klik op het slot om de code. Voor escape rooms en uitdagingen: de juiste code opent het.",
