  "Ese no es el código.": "Dat is niet de code.",
  "Intentos (0: sin límite)": "Pogingen (0: onbeperkt)",
  "No dejar pasar de esta diapositiva hasta abrirlo (a su ritmo, en el visor y en el HTML exportado)": "Niet voorbij deze dia laten gaan tot het open is (in eigen tempo, in de viewer en in de geëxporteerde HTML)",
  "En la presentación exportada no va el código, sino una huella cifrada (SHA-256): mirar el código de la página no da la respuesta. Un número corto se puede adivinar probando.": "De geëxporteerde presentatie bevat de code niet, alleen een versleutelde vingerafdruk (SHA-256): de broncode van de pagina verraadt het antwoord niet. Een kort getal is te raden door te proberen.",
