  "Generar desde<br>una hoja": "Genereren uit<br>spreadsheet",
  "Diplomas, tarjetas con nombre, certificados…: escribe marcadores como {{nombre}} o {{nota}} en los textos de la diapositiva y elige una hoja de cálculo; se hace una copia de la diapositiva por cada fila, con sus datos.": "Diploma's, naamkaartjes, certificaten…: schrijf plaatshouders zoals {{nombre}} of {{nota}} in de teksten van de dia en kies een spreadsheet; voor elke rij komt er een kopie van de dia met de gegevens.",
