  "Actividad: rueda de letras": "Activiteit: letterwiel",
  "Rueda de letras": "Letterwiel",
  "Una letra por línea: «A = respuesta = pista» (sin la letra, vale la primera de la respuesta; «~» delante para «Contiene la…» en lugar de «Empieza por la…»; «a|b» si valen dos respuestas). En los móviles salen la rueda, la letra y la pista, nunca la respuesta. Al presentar, la tecla J la juega en la pantalla con una sola persona, sin móviles.": "Eén letter per regel: ‘A = antwoord = hint’ (zonder letter geldt de eerste van het antwoord; ‘~’ ervoor voor ‘Bevat de…’ in plaats van ‘Begint met…’; ‘a|b’ als twee antwoorden goed zijn). Op de telefoons verschijnen het wiel, de letter en de hint, nooit het antwoord. Tijdens het presenteren speelt de J-toets het op het scherm met één persoon, zonder telefoons.",
